/**
 * Renders the social share card to `public/og.png`.
 *
 * An OpenGraph image has to be a bitmap: crawlers do not render SVG, so this
 * is the one asset on the site that cannot be drawn live. That makes it the
 * one asset that can go stale silently, which is why it is generated by a
 * script rather than exported by hand from a design tool.
 *
 * Chromium does the rendering rather than Satori (`next/og`) because the brand
 * faces ship as WOFF2 and Satori cannot read WOFF2. Rendering in a browser
 * gets real Quicksand and Nunito Sans instead of a substituted system sans.
 *
 * Run after any change to the card, the palette or the fonts:
 *
 *     node scripts/build-og-image.mjs
 */
import { chromium } from "playwright";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const template = join(here, "og-card.html");
const output = join(here, "..", "public", "og.png");

const browser = await chromium.launch(
  process.env.PW_CHROMIUM_PATH
    ? { executablePath: process.env.PW_CHROMIUM_PATH }
    : {},
);

try {
  const page = await browser.newPage({
    viewport: { width: 1200, height: 630 },
    deviceScaleFactor: 1,
  });
  await page.goto(`file://${template}`);
  // Fonts load from disk, but layout still settles a frame later.
  await page.evaluate(() => document.fonts.ready);
  await page.screenshot({ path: output, type: "png" });
  console.log(`Wrote ${output}`);
} finally {
  await browser.close();
}
